SELECT s.*, b.project_id, v.version_no, (SELECT COALESCE(SUM((i.base_quantity - i.excluded_quantity + i.adjustment_quantity) * i.unit_price), 0) FROM billing_statement_items i WHERE i.statement_id = s.statement_id) + (SELECT COALESCE(SUM(o.quantity * o.unit_price), 0) FROM billing_statement_other_items o WHERE o.statement_id = s.statement_id) AS subtotal FROM billing_statements s JOIN billing_bases b ON s.base_id = b.base_id LEFT JOIN billing_base_versions v ON s.version_id = v.version_id WHERE b.project_id = #{projectId}
AND s.status = '確定'
ORDER BY s.billing_month DESC, s.statement_id DESC

