UPDATE billing_statement_items
SET adjustment_quantity =
#{adjustmentQuantity},
adjustment_reason = #{adjustmentReason}
WHERE
statement_item_id = #{statementItemId}
AND statement_id =
#{statementId}

UPDATE billing_statement_other_items
SET quantity =
#{quantity},
unit_price = #{unitPrice}
WHERE statement_other_item_id =
#{statementOtherItemId}
AND statement_id = #{statementId}
